use std::collections::{BinaryHeap, VecDeque};

fn smallest_k(nums: &[i64], k: usize) -> Vec<i64> {
    let mut heap = BinaryHeap::new();
    for &n in nums {
        heap.push(n);
        if heap.len() > k {
            heap.pop();
        }
    }
    heap.into_sorted_vec()
}

fn sliding_max(nums: &[i64], window: usize) -> Vec<i64> {
    if window == 0 || window > nums.len() {
        return Vec::new();
    }
    let mut out = Vec::new();
    let mut q: VecDeque<usize> = VecDeque::new();
    for i in 0..nums.len() {
        while let Some(&back) = q.back() {
            if nums[back] <= nums[i] { q.pop_back(); } else { break; }
        }
        q.push_back(i);
        if q[0] + window <= i {
            q.pop_front();
        }
        if i + 1 >= window {
            out.push(nums[q[0]]);
        }
    }
    out
}

unitTests:
test("smallest k", || {
    check_eq(smallest_k(&[5, 1, 9, 3, 7], 3), vec![1, 3, 5]);
    check_eq(smallest_k(&[4, 4, 2], 2), vec![2, 4]);
    check_eq(smallest_k(&[3], 5), vec![3]);
    check_eq(smallest_k(&[3, 1], 0), Vec::<i64>::new());
});

test("sliding max", || {
    check_eq(sliding_max(&[1, 3, -1, -3, 5, 3, 6], 3), vec![3, 3, 5, 5, 6]);
    check_eq(sliding_max(&[9, 8, 7], 1), vec![9, 8, 7]);
    check_eq(sliding_max(&[2, 2, 2], 3), vec![2]);
    check_eq(sliding_max(&[1, 2], 3), Vec::<i64>::new());
    check_eq(sliding_max(&[1, 2], 0), Vec::<i64>::new());
});

